-- Silver transactions: validated, typed, de-duplicated, idempotent.
--
-- transactions_checked drops rows that fail TXN_RULES (the rules that route them to quarantine) and
-- records pass/fail metrics per rule. Rules are written against the raw string columns, so they run
-- before typing. CREATE TEMPORARY VIEW cannot carry CONSTRAINT clauses, hence CREATE LIVE VIEW.
CREATE LIVE VIEW transactions_checked (
  CONSTRAINT txn_id_present EXPECT (coalesce(trim(txn_id) <> '', false)) ON VIOLATION DROP ROW,
  CONSTRAINT merchant_id_present EXPECT (coalesce(trim(merchant_id) <> '', false)) ON VIOLATION DROP ROW,
  CONSTRAINT amount_is_positive_integer EXPECT (coalesce(try_cast(amount_minor AS BIGINT) > 0, false)) ON VIOLATION DROP ROW,
  CONSTRAINT currency_supported EXPECT (coalesce(currency IN ('AUD', 'CAD', 'CHF', 'DKK', 'EUR', 'GBP', 'JPY', 'NOK', 'PLN', 'SEK', 'USD'), false)) ON VIOLATION DROP ROW,
  CONSTRAINT txn_type_known EXPECT (coalesce(txn_type IN ('SALE', 'REFUND', 'CHARGEBACK'), false)) ON VIOLATION DROP ROW,
  CONSTRAINT auth_ts_parses EXPECT (try_cast(auth_ts AS TIMESTAMP) IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT settle_not_before_auth EXPECT (settle_date IS NULL OR coalesce(try_cast(settle_date AS DATE) >= to_date(try_cast(auth_ts AS TIMESTAMP)), false)) ON VIOLATION DROP ROW,
  CONSTRAINT no_rescued_data EXPECT (_rescued_data IS NULL) ON VIOLATION DROP ROW
)
AS SELECT * FROM STREAM(transactions_raw);

-- Typed shape of the Silver table (same casts as lib.transforms.type_transactions). Assumes rules passed.
CREATE TEMPORARY VIEW transactions_validated
AS SELECT
  trim(txn_id) AS txn_id,
  trim(merchant_id) AS merchant_id,
  outlet_id,
  merchant_name,
  mcc,
  merchant_country,
  terminal_id,
  card_scheme,
  card_pan_masked,
  card_token,
  txn_type,
  upper(trim(currency)) AS currency,
  try_cast(amount_minor AS BIGINT) AS amount_minor,
  try_cast(auth_ts AS TIMESTAMP) AS auth_ts,
  to_date(try_cast(auth_ts AS TIMESTAMP)) AS auth_date,
  try_cast(settle_date AS DATE) AS settle_date,
  auth_code,
  response_code,
  _source_file,
  _batch_id,
  _ingested_at
FROM STREAM(transactions_checked);

CREATE OR REFRESH STREAMING TABLE transactions (
  txn_id STRING COMMENT 'Acquirer transaction reference. Unique key.',
  merchant_id STRING COMMENT 'Merchant number.',
  outlet_id STRING COMMENT 'Merchant outlet (site) number.',
  merchant_name STRING COMMENT 'Merchant trading name.',
  mcc STRING COMMENT 'ISO 18245 merchant category code.',
  merchant_country STRING COMMENT 'ISO 3166 alpha-2 country of the merchant.',
  terminal_id STRING COMMENT 'Terminal identifier.',
  card_scheme STRING COMMENT 'Card scheme.',
  card_pan_masked STRING COMMENT 'Masked card number. Synthetic, tagged PII.',
  card_token STRING COMMENT 'Tokenised card identifier. Synthetic, tagged PII.',
  txn_type STRING COMMENT 'SALE, REFUND or CHARGEBACK.',
  currency STRING COMMENT 'ISO 4217 transaction currency.',
  amount_minor BIGINT COMMENT 'Unsigned amount in currency minor units. Direction comes from txn_type.',
  auth_ts TIMESTAMP COMMENT 'Authorisation timestamp.',
  auth_date DATE COMMENT 'Authorisation date. Drives the FX rate date and the reporting period.',
  settle_date DATE COMMENT 'Settlement date.',
  auth_code STRING COMMENT 'Issuer authorisation code.',
  response_code STRING COMMENT 'ISO 8583 response code.',
  _source_file STRING COMMENT 'Landing file this row came from.',
  _batch_id STRING COMMENT 'Landing batch identifier.',
  _ingested_at TIMESTAMP COMMENT 'Bronze ingestion time; the Auto CDC sequence column (latest wins).'
)
CLUSTER BY (auth_date, merchant_id)
COMMENT 'Typed, validated, de-duplicated card transactions (one row per txn_id, latest ingest wins). Synthetic data generated by dbldatagen. No real cardholder or merchant data.'
TBLPROPERTIES (
  'quality' = 'silver',
  'data_classification' = 'confidential',
  'delta.enableRowTracking' = 'true'
);

-- Deduplication. The Python pipeline uses withWatermark + dropDuplicatesWithinWatermark, which has no SQL
-- equivalent. In SQL the dedup is done by Auto CDC itself: SCD type 1 keeps, per txn_id, the row with
-- the highest SEQUENCE BY value, whether the duplicates arrive in one micro-batch or in different ones.
-- Sequencing by _ingested_at alone is not enough: duplicates read in the same Auto Loader batch share
-- the same current_timestamp(), and equal sequence values for one key are non-deterministic. The
-- STRUCT adds _source_file as a tie-breaker (struct comparison is field by field), so a duplicate
-- landed in a different file resolves deterministically. A duplicate inside the SAME file still ties.
CREATE FLOW transactions_cdc
AS AUTO CDC INTO transactions
FROM STREAM(transactions_validated)
KEYS (txn_id)
SEQUENCE BY STRUCT(_ingested_at, _source_file)
STORED AS SCD TYPE 1;
